js:
        let rid = input.match(/\/(\d+)/)[1];
        // 尝试官方API获取流
        let apis = [
            'https://www.douyu.com/lapi/live/getH5Play/' + rid + '?rpos=1',
            'https://playweb.douyucdn.cn/lapi/live/getH5Play/' + rid + '?rpos=1'
        ];
        function tryApi(apiUrl) {
            try {
                let tt = (Date.now() / 1000).toFixed(0);
                let sign = md5(rid + tt + 'zNzMV1y4EMxOHS6I5WKm');
                let url = apiUrl + '&tt=' + tt + '&sign=' + sign;
                let html = request(url, { headers: { 'User-Agent': 'MOBILE_UA' } });
                let data = JSON.parse(html);
                if (data.error === 0 && data.data) {
                    let stream = data.data;
                    let flvUrl = stream.rtmp_url + '/' + stream.rtmp_live;
                    return { jx: 0, url: flvUrl, parse: 0, header: JSON.stringify({ 'user-agent': 'Mozilla/5.0' }) };
                }
            } catch (e) { log('API尝试失败: ' + e.message); }
            return null;
        }
        for (let api of apis) {
            let result = tryApi(api);
            if (result) { input = result; return; }
        }
        // 备选：第三方代理
        input = { jx: 0, url: 'https://live.iill.top/douyu/' + rid, parse: 0, header: JSON.stringify({ 'user-agent': 'MXPlayer/1.86.0' }) };

